  provider.conversations = () => { const pid = S.providerPersona; const p = byId(pid); const managing = S.stage[pid] === 'managing' || S.stage[pid] === 'upgraded'; const list = enquiriesFor(pid); const answered = list.filter(e => e.state === 'sent').length; return `<div><h1 class="page-title">Conversations</h1><p class="sub">Every enquiry from a family — platform message, e-mail, missed call — with a drafted answer from your knowledge files. Speed is the point: the first to answer wins the trial (research §2).</p></div>${managing ? `<section class="tiles">${tile('Waiting', String(list.filter(e => e.state === 'waiting').length), 'enquiries · sample')}${tile('Answered this week', String(answered), 'from your approvals')}${tile('Reply time', answered ? '4 min' : '—', answered ? '▼ from 3 h · sample' : 'nothing sent yet', answered ? 'up' : '')}${tile('Missed calls texted back', String(list.filter(e => e.channel === 'Missed call' && e.state === 'sent').length), 'of ' + list.filter(e => e.channel === 'Missed call').length)}</section><section class="stack"><div class="section-head"><h2>Inbox — ${esc(p.name)}</h2><span class="meta">${S.ai.provider ? 'AI drafts on' : 'AI drafts off — templates from your files'}</span></div>${list.map(e => enquiryCard(e, pid)).join('')}</section>` : '<div class="empty">Conversations unlock once you manage your page — open Today and apply.</div>'}`; };
